### 🚀 Production-Ready JWT Auth + Refresh Token + Redis Rate Limiting Middleware for Express.js

```typescript
import express, { NextFunction, Request, Response } from 'express';
import jwt from 'jsonwebtoken';
import redis from 'redis';
import rateLimit from 'express-rate-limit';
import { secretKey, refreshSecretKey } from './config';

const app = express();

// Redis Client
const redisClient = redis.createClient({
  host: 'localhost',
  port: 6379,
});

// JWT Secret Keys
const jwtSecret = secretKey;
const refreshJwtSecret = refreshSecretKey;

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 100, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders:true, // return rate limit info in the `RateLimit-*` headers
  legacyHeaders:, // disable the `X-RateLimit-*` headers
  handler: (req, res, next) => {
    res.status(429).json({ message: 'Too many requests, please try again later.' });
  },
});

// JWT Middleware
const jwtMiddleware = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const token = req.headers['x-access-token'] as string;
    if (!token) {
      throw new Error('No token provided');
    }

    const decoded = jwt.verify(token, jwtSecret);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ message: 'Invalid token' });
  }
};

// Refresh Token Middleware
const refreshJwtMiddleware = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const refreshToken = req.headers['x-refresh-token'] as string;
    if (!refreshToken) {
      throw new Error('No refresh token provided');
    }

    const decoded = jwt.verify(refreshToken, refreshJwtSecret);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ message: 'Invalid refresh token' });
  }
};

// Redis Rate Limiting Middleware
const redisRateLimitMiddleware = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const ip = req.ip;
    const key = `rate-limit:${ip}`;
    const value = await redisClient.get(key);
    if (value) {
      const rateLimit = JSON.parse(value);
      if (rateLimit.remaining <= ) {
        res.status(429).json({ message: 'Too many requests, please try again later.' });
      } else {
        next();
      }
    } else {
      redisClient.set(key, JSON.stringify({ remaining: 100, reset: Date.now() + 15 * 60 * 100 }));
      next();
    }
  } catch (error) {
    res.status(500).json({ message: 'Internal Server Error' });
  }
};

// Apply Middlewares
app.use(limiter);
app.use(redisRateLimitMiddleware);
app.use(jwtMiddleware);
app.use(refreshJwtMiddleware);

// Routes
app.get('/api/user', (req: Request, res: Response) => {
  res.json({ message: 'Hello, World!' });
});

// Start Server
const port = 300;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
```

### 🚀 Configuration

Create a `config.js` file to store your secret keys and Redis connection details:

```typescript
export const secretKey = 'your-jwt-secret-key';
export const refreshSecretKey = 'your-refresh-jwt-secret-key';
export const redisHost = 'localhost';
export const redisPort = 6379;
```

### 🚀 Explanation

This middleware stack includes:

1.  **Rate Limiting:** Using `express-rate-limit`, we limit the number of requests from each IP address to 100 within a 15-minute window.
2.  **JWT Authentication:** With `jsonwebtoken`, we verify the JWT token sent in the `x-access-token` header. If the token is invalid or missing, we return a 401 response.
3.  **Refresh Token:** Using `jsonwebtoken` again, we verify the refresh token sent in the `x-refresh-token` header. If the token is invalid or missing, we return a 401 response.
4.  **Redis Rate Limiting:** We store the rate limit information in Redis using the `redis` client. If the IP address is rate-limited, we return a 429 response.

### 🚀 Usage

To use this middleware stack, simply import and apply the middlewares to your Express.js application:

```typescript
import express from 'express';
import { jwtMiddleware, refreshJwtMiddleware, redisRateLimitMiddleware } from './middleware';

const app = express();

app.use(redisRateLimitMiddleware);
app.use(jwtMiddleware);
app.use(refreshJwtMiddleware);

// Routes
app.get('/api/user', (req: Request, res: Response) => {
  res.json({ message: 'Hello, World!' });
});

// Start Server
const port = 300;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
```

Remember to replace the secret keys and Redis connection details with your own values.
